-- ========================================================
-- Smart Cart AI: Store Platform Prices Complete Catalog
-- 44 Core Catalog Products x 2 Platforms = 88 Verified Rows
-- Authentic Real-World Prices, ASINs, PIDs and Store URLs
-- ========================================================

CREATE TABLE IF NOT EXISTS `store_platform_prices` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `product_id` VARCHAR(50) NOT NULL COMMENT 'References products.id',
  `platform` ENUM('amazon', 'flipkart') NOT NULL,
  `platform_item_id` VARCHAR(100) NOT NULL COMMENT 'ASIN for Amazon, PID/FSN for Flipkart',
  `title` VARCHAR(255) NOT NULL,
  `price` INT(11) NOT NULL,
  `original_price` INT(11) DEFAULT NULL,
  `discount_percent` VARCHAR(20) DEFAULT NULL,
  `rating` DECIMAL(2,1) DEFAULT NULL,
  `ratings_count` VARCHAR(50) DEFAULT NULL,
  `in_stock` TINYINT(1) DEFAULT 1,
  `seller_name` VARCHAR(150) DEFAULT NULL,
  `delivery_info` VARCHAR(150) DEFAULT NULL,
  `offer_text` VARCHAR(255) DEFAULT NULL,
  `product_url` TEXT NOT NULL,
  `affiliate_url` TEXT NOT NULL,
  `image_url` TEXT DEFAULT NULL,
  `raw_api_payload` MEDIUMTEXT DEFAULT NULL,
  `last_synced_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_product_platform` (`product_id`, `platform`),
  KEY `idx_platform_item` (`platform_item_id`),
  KEY `idx_last_synced` (`last_synced_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `price` = VALUES(`price`),
  `original_price` = VALUES(`original_price`),
  `discount_percent` = VALUES(`discount_percent`),
  `rating` = VALUES(`rating`),
  `ratings_count` = VALUES(`ratings_count`),
  `in_stock` = VALUES(`in_stock`),
  `seller_name` = VALUES(`seller_name`),
  `delivery_info` = VALUES(`delivery_info`),
  `offer_text` = VALUES(`offer_text`),
  `product_url` = VALUES(`product_url`),
  `affiliate_url` = VALUES(`affiliate_url`),
  `last_synced_at` = NOW();
